tool.command:
Rscript --vanilla -e '
    library(ampvis2); library(readr); library(phyloseq);
    input <- readRDS("$otu_table");
    if (!is.null("$metadata")) {
        metadata <- readRDS("$metadata");
        input <- amp_load(input, metadata=metadata, guess_metadata=!!guess_metadata);
    }
    if (!is.null("$taxonomy")) {
        taxonomy <- readRDS("$taxonomy");
        input <- amp_load(input, taxonomy=taxonomy);
    }
    if (!is.null("$tree")) {
        tree <- read_tree("$tree");
        input <- amp_load(input, tree=tree);
    }
    if (!is.null("$fasta")) {
        fasta <- read_fasta("$fasta");
        input <- amp_load(input, fasta=fasta);
    }
    output_rds <- "$output_rds";
    saveRDS(input, file=output_rds);
    if (output_lists) {
        if (!is.null(metadata)) {
            metadata_list <- data.frame(
                Variable=names(metadata),
                Values=apply(metadata, 2, function(x) paste(unique(x), collapse=", ")),
                isSampleID=names(metadata) == "SampleID",
                Type=map_chr(metadata, typeof)
            );
            write.table(metadata_list, file="$metadata_list", sep="\t", row.names=FALSE);
        }
        if (!is.null(taxonomy)) {
            taxonomy_list <- data.frame(Taxonomy=unique(unlist(taxonomy)));
            write.table(taxonomy_list, file="$taxonomy_list", sep="\t", row.names=FALSE);
        }
    }
'
